<?php require 'bootstrap.php';$u=need_user();$err='';$ok='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim((string)($_POST['channel']??''));$topic=trim((string)($_POST['topic']??''));if(!str_starts_with($name,'#'))$name='#'.$name;if(!valid_channel($name))$err='Channelname ungültig.';else{try{db()->beginTransaction();$q=db()->prepare("INSERT INTO ls_channels(channel_name,channel_name_normalized,founder_user_id,topic) VALUES(?,?,?,?)");$q->execute([$name,mb_strtolower($name,'UTF-8'),$u['id'],$topic?:null]);$cid=(int)db()->lastInsertId();$q=db()->prepare("INSERT INTO ls_channel_access(channel_id,user_id,access_role) VALUES(?,?,'founder')");$q->execute([$cid,$u['id']]);db()->commit();$ok=$name.' wurde registriert.';}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err=str_contains($e->getMessage(),'Duplicate')?'Channel ist bereits registriert.':'Channel konnte nicht registriert werden.';}}}$q=db()->prepare("SELECT c.* FROM ls_channels c WHERE c.founder_user_id=? AND c.is_active=1 ORDER BY c.channel_name");$q->execute([$u['id']]);$channels=$q->fetchAll();$title='Meine Channels';require 'header.php';?><section class="panel"><span>CHANNEL CONTROL</span><h1>Meine Channels</h1><?php if(isset($_GET['welcome'])):?><div class="success">Account erstellt. Willkommen @<?=e($u['username'])?> 👋</div><?php endif;?><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><?php if($ok):?><div class="success"><?=e($ok)?></div><?php endif;?><div class="split"><div><h2>Registriert</h2><?php if(!$channels):?><p class="hint">Noch kein Channel registriert.</p><?php endif;?><?php foreach($channels as $c):?><article class="channel"><b><?=e($c['channel_name'])?></b><span>Founder</span><small><?=e((string)($c['topic']??'Kein Topic'))?></small></article><?php endforeach;?></div><div><h2>Channel registrieren</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Channel<input name="channel" placeholder="#meinchannel" maxlength="64" required></label><label>Topic<input name="topic" maxlength="512" placeholder="Optional"></label><button>Channel registrieren</button></form></div></div></section><?php require 'footer.php';?>
